INSERT INTO actividad_bienestar (nombre, descripcion, categoria, duracion_estimada, activa) VALUES
('Respira y reinicia', 'Sientate con la espalda recta. Inhala 4 segundos, sostén 4, exhala 4 y descansa 4. Repite siguiendo el ritmo del círculo.', 'RESPIRAR', 3, TRUE),
('Respiración cuadrada', 'Inhala contando hasta 4, sostén el aire 4 segundos, exhala en 4 y mantén los pulmones vacíos 4 segundos. Repite durante 4 minutos.', 'RESPIRAR', 4, TRUE),
('Movilidad de cuello y hombros', 'Gira lentamente los hombros hacia atrás 10 veces y luego inclina el cuello a cada lado sin forzar. Mantén una respiración tranquila.', 'MOVERTE', 6, TRUE),
('Descanso visual 20-20-20', 'Cada 20 minutos mira un objeto situado a unos 6 metros durante 20 segundos y parpadea con calma.', 'DESCANSAR', 2, TRUE),
('Escaneo corporal breve', 'Recorre mentalmente tu cuerpo de los pies a la cabeza observando sensaciones sin juzgarlas. Relaja cada zona al exhalar.', 'DESCANSAR', 5, TRUE);
